const campaign = $json;
const profile = $('Get Profiles To Score').item.json;

const systemPrompt = `You are a LinkedIn profile scorer. Given a search goal and a candidate's profile data, score the candidate on up to 6 KPIs, each 0-100, following these exact rules:

1. field (weight 25%): quick, broad check of professional domain, using only headline, job title, industry, and top skills. 80-100 clearly in target field, 50-79 adjacent field, 20-49 weak signal, 0 no match.
2. location (weight 20%): geographic fit from the profile location field. 100 target city/region, 90 same broader region, 40 neighboring region with ties, 0 elsewhere.
3. role_seniority (weight 15%): does their role/seniority match the target role type, from job title, employer type, years in role. 90-100 exact senior match, 60-89 adjacent level, 30-59 junior/related, 0 unrelated.
4. topic (weight 20%): a DEEP check into the About section, experience descriptions, publications, projects, and courses for the SPECIFIC topic in the search goal (not just the broad field). Any single real, explicit example is enough for 80-100, even if it is only one project among many. 50-79 topic appears in text but not as a clear explicit project. 20-49 related field only, no direct mention. 0 no mention.
5. network_proximity (weight 10%, OMIT ENTIRELY if connection-degree or mutual-connection data is not present in the input - never guess or default this to 0): 90-100 2nd degree with 5+ mutuals, 60-89 2nd degree with 1-4 mutuals, 30-59 3rd degree with a shared school/group, 0-29 3rd+ degree with no shared context.
6. activity (weight 10%): recency of posts/comments/reactions and profile signals. 80-100 active within 30 days, 50-79 within 90 days, 20-49 within a year, 0-19 dormant. SENIORITY OFFSET: if role_seniority scored 80 or higher, activity must not be scored below 50, no matter how quiet the profile looks.

Output ONLY valid JSON, no prose, in exactly this shape:
{"kpi_scores": [{"kpi": "field", "score": 0, "reason": "one short sentence"}, ...]}
Include one entry per KPI you can actually measure. Omit "network_proximity" entirely when degree/mutuals data is not given - never include it with a guessed score.`;

const userMessage = `Search goal: ${campaign.search_goal}

Candidate profile:
Name: ${profile.full_name || ''}
Headline: ${profile.headline || ''}
Location: ${profile.location || ''}
Additional data: ${JSON.stringify(profile.raw_data || {})}`;

return {
  json: {
    profile_id: profile.id,
    campaign_id: campaign.id,
    kpi_weights: campaign.kpi_weights,
    require_field: campaign.require_field,
    require_location: campaign.require_location,
    systemPrompt,
    userMessage
  }
};

const raw = $json;
const prompt = $('Build Scoring Prompt').item.json;

let parsed;
try {
  const content = raw.choices[0].message.content;
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  throw new Error('Could not parse LLM response as JSON: ' + e.message);
}

const kpiScores = parsed.kpi_scores || [];
const weights = prompt.kpi_weights;

const seniority = kpiScores.find(k => k.kpi === 'role_seniority');
const activity = kpiScores.find(k => k.kpi === 'activity');
if (seniority && activity && seniority.score >= 80 && activity.score < 50) {
  activity.score = 50;
}

const fieldScore = kpiScores.find(k => k.kpi === 'field');
const locationScore = kpiScores.find(k => k.kpi === 'location');
const filteredOut = !!(
  (prompt.require_field && fieldScore && fieldScore.score === 0) ||
  (prompt.require_location && locationScore && locationScore.score === 0)
);

const totalWeight = kpiScores.reduce((sum, k) => sum + (weights[k.kpi] || 0), 0);
const rawSum = kpiScores.reduce((sum, k) => sum + k.score * (weights[k.kpi] || 0), 0);
const composite = totalWeight > 0 ? Math.round((rawSum / totalWeight) * 10000) / 100 : 0;

return {
  json: {
    profile_id: prompt.profile_id,
    kpi_scores: kpiScores,
    composite,
    filtered_out: filteredOut
  }
};
